class Solution {
public:
    int deleteAndEarn(vector<int>& nums) {
        int maxVal = 0;
        for (int x : nums) maxVal = max(maxVal, x);

        vector<long long> points(maxVal + 1, 0);
        for (int x : nums) points[x] += x;

        long long prev2 = 0, prev1 = points[1];
        for (int i = 2; i <= maxVal; i++) {
            long long curr = max(prev1, prev2 + points[i]);
            prev2 = prev1;
            prev1 = curr;
        }

        return (int)prev1;
    }
};
